(()=>{'use strict';const D=window.BASE_DATA,F=window.Factory,$=id=>document.getElementById(id);const state={zone:'Z01',mode:'after',scheme:'A',view:F?'interior':'plan',walk:false,major:'',sensor:'normal',tour:0};let yaw=0,pitch=.07,orbit={theta:.55,phi:.8,r:62},target={x:0,y:1,z:0};const keys={},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('major').innerHTML+=D.majors.map(x=>`<option>${esc(x)}</option>`).join('');
function selected(){return D.zones.find(z=>z.id===state.zone)}
function taskCard(t){return `<article class="taskCard"><small>${t.id} / ${esc(t.lead)} · 建议 ${t.hours} 学时</small><h3>${esc(t.name)}</h3><p><b>输入</b>　${esc(t.input)}</p><p><b>实训</b>　${esc(t.action)}</p><p><b>交付</b>　${esc(t.output)}</p></article>`}
function openModal(title,html){$('modalTitle').textContent=title;$('modalContent').innerHTML=html;$('modal').showModal()}
$('closeModal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal'))$('modal').close()});
function renderZones(){const z=selected();$('zoneList').innerHTML=D.zones.map(q=>`<button class="zoneButton ${q.id===z.id?'selected':''} ${state.major&&!q.lead.concat(q.support).includes(state.major)?'dim':''}" data-zone="${q.id}" style="--zcolor:${q.color}"><i>${q.id.slice(1)}</i><span>${q.name}</span></button>`).join('');$('zoneDetail').innerHTML=`<span class="zoneId">${z.id} / ${z.position}</span><h2>${z.name}</h2><p>${z.purpose}</p><div class="metaLabel">主责专业</div><div class="pills">${z.lead.map(s=>`<span class="pill">${s}</span>`).join('')}</div><div class="metaLabel">协同专业</div><p>${z.support.join(' · ')}</p><div class="metaLabel">可开展实训 / ${z.tasks.length} 项</div>${D.tasks.filter(t=>t.zone===z.id).map(t=>`<button class="taskLink" data-task="${t.id}"><em>${t.id}</em>${t.name}</button>`).join('')}<div class="metaLabel">工位与设施</div><p>${z.seats}<br>${z.equipment}</p>`;$('zoneList').querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>chooseZone(b.dataset.zone,true));$('zoneDetail').querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openModal('实训任务',taskCard(D.tasks.find(t=>t.id===b.dataset.task))));drawPlan();}
function chooseZone(id,focus=false){state.zone=id;renderZones();if(F&&focus&&state.view!=='plan'){let z=selected();state.walk=false;$('walkHelp').hidden=true;$('joystick').hidden=true;state.view='focus';F.groups.roof.visible=true;F.groups.walls.visible=true;const x=z.x===0?0:(z.x<0?-6.3:6.3);F.camera.position.set(x,3.1,z.z+5);F.camera.lookAt(z.x,1.1,z.z);}}
$('major').onchange=e=>{state.major=e.target.value;const q=D.zones.find(z=>z.lead.includes(state.major));if(q)state.zone=q.id;renderZones()};
function drawPlan(){let svg=$('plan');let sx=x=>300+x*11,sy=z=>300+z*11;let body=`<rect x="99" y="64" width="402" height="470" rx="3" fill="#d4dad1" stroke="#7c8b7c" stroke-width="3"/><rect x="280" y="70" width="40" height="458" fill="#f0eee2"/><text x="300" y="555" text-anchor="middle" font-size="11" fill="#637769">入口侧 / 主通道</text>`;
if(state.mode==='after'){D.zones.forEach(z=>{let active=z.id===state.zone,dim=state.major&&!z.lead.concat(z.support).includes(state.major);let rects=z.x===0?[[-7.6,5.6],[2,5.6]]:[[z.x-z.w/2,z.w]];for(let [x,w] of rects){body+=`<g class="planZone" data-zone="${z.id}" opacity="${dim?.25:1}"><rect x="${sx(x)}" y="${sy(z.z-z.d/2)}" width="${w*11}" height="${z.d*11}" rx="3" fill="${z.color}" fill-opacity="${active?.6:.25}" stroke="${active?'#294540':z.color}" stroke-width="${active?2.5:1}"/><text x="${sx(x+w/2)}" y="${sy(z.z)-5}" text-anchor="middle" fill="#263d3c" font-size="12" font-weight="600">${z.id}</text><text x="${sx(x+w/2)}" y="${sy(z.z)+13}" text-anchor="middle" fill="#263d3c" font-size="9">${z.short}</text></g>`;}});let tables=[[-4.8,-14],[4.8,-14],[-4.8,-4],[4.8,-4],[-4.8,4]];tables.forEach(([x,z],i)=>{let exhibit=state.scheme==='B'&&i>2;body+=`<rect x="${sx(x)-20}" y="${sy(z)-7}" width="40" height="14" fill="${exhibit?'#729486':'#ab9775'}" rx="2"/>`;if(!exhibit)for(let dx of [-16,-6,6,16])for(let dz of [-12,12])body+=`<rect x="${sx(x)+dx-3}" y="${sy(z)+dz-3}" width="6" height="6" fill="#537968"/>`;});}else{body+=`<rect x="115" y="242" width="56" height="204" fill="#d6c6ab" stroke="#b28050"/><text x="143" y="340" text-anchor="middle" font-size="11" fill="#736a57">风电设备</text><text x="300" y="290" text-anchor="middle" font-size="15" fill="#8e998c">原始开放厂房</text><text x="300" y="312" text-anchor="middle" font-size="10" fill="#8e998c">保留主体柱网与屋架</text>`;}
for(let x of [-18,-9,9,18])for(let z of [-21,-14,-7,0,7,14,21])body+=`<rect x="${sx(x)-4}" y="${sy(z)-4}" width="8" height="8" fill="#626f66"/>`;body+=`<text x="300" y="587" text-anchor="middle" font-size="9" fill="#899388">比例示意 · 方位以入口为基准 · 非测绘平面图</text>`;svg.innerHTML=body;svg.querySelectorAll('[data-zone]').forEach(e=>{e.setAttribute('tabindex','0');e.setAttribute('role','button');e.onclick=()=>chooseZone(e.dataset.zone);e.onkeydown=k=>{if(k.key==='Enter')chooseZone(e.dataset.zone)}});}
function updateMode(){if(F)F.upgrade.setMode(state.mode,state.scheme);document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));document.querySelectorAll('[data-scheme]').forEach(b=>{b.classList.toggle('active',b.dataset.scheme===state.scheme);b.disabled=state.mode==='before'});$('modeTitle').textContent=state.mode==='before'?'改造前 / 照片推估模型':`改造后 / ${state.scheme==='A'?'教学优先':'展示优先'}`;$('schemeCount').textContent=state.mode==='before'?'原始设备与开放空间':state.scheme==='A'?'5 个项目组 · 40 个协作席位':'3 个项目组 · 24 个协作席位 + 2 组展台';drawPlan();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;updateMode()});document.querySelectorAll('[data-scheme]').forEach(b=>b.onclick=()=>{state.scheme=b.dataset.scheme;updateMode()});
function view(mode){if(!F&&mode!=='plan')return;state.view=mode;state.walk=mode==='walk';$('hint').textContent=mode==='plan'?'点击分区查看专业与实训':'拖动旋转 · 滚轮缩放 · 点击区域查看实训';$('planWrap').hidden=mode!=='plan';$('viewport').hidden=mode==='plan';$('walkHelp').hidden=!state.walk;$('joystick').hidden=!state.walk;if(F){F.groups.roof.visible=mode!=='bird';F.groups.walls.visible=mode!=='bird';if(mode==='interior'||mode==='walk'){F.camera.position.set(0,mode==='walk'?1.72:2.6,18.3);yaw=0;pitch=mode==='walk'?.015:.07;F.camera.rotation.order='YXZ';F.camera.rotation.set(pitch,yaw,0);}if(mode==='bird'){orbit={theta:.55,phi:.8,r:62};updateOrbit();}}}
$('interior').onclick=()=>view('interior');$('bird').onclick=()=>view('bird');$('planBtn').onclick=()=>view('plan');$('walk').onclick=()=>view(state.walk?'interior':'walk');$('roof').onclick=()=>{if(F)F.groups.roof.visible=!F.groups.roof.visible};$('tour').onclick=()=>{state.mode='after';updateMode();let z=D.zones[state.tour++%D.zones.length];chooseZone(z.id,true);};
function updateOrbit(){F.camera.position.set(Math.sin(orbit.theta)*Math.sin(orbit.phi)*orbit.r,Math.cos(orbit.phi)*orbit.r,Math.cos(orbit.theta)*Math.sin(orbit.phi)*orbit.r);F.camera.lookAt(target.x,target.y,target.z);}
function canMove(x,z){return Math.abs(x)<17.4&&Math.abs(z)<20.3&&!F.colliders.some(b=>x>b.minX-.18&&x<b.maxX+.18&&z>b.minZ-.18&&z<b.maxZ+.18)}
if(F){const c=F.renderer.domElement;let drag=false,last={x:0,y:0},down={x:0,y:0};c.addEventListener('pointerdown',e=>{drag=true;last=down={x:e.clientX,y:e.clientY};c.setPointerCapture(e.pointerId)});c.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-last.x,dy=e.clientY-last.y;last={x:e.clientX,y:e.clientY};if(state.view==='bird'){orbit.theta-=dx*.005;orbit.phi=Math.max(.15,Math.min(1.5,orbit.phi+dy*.004));updateOrbit();}else{if(state.view==='focus'){F.camera.rotation.order='YXZ';yaw=F.camera.rotation.y;pitch=F.camera.rotation.x;state.view='interior';}yaw-=dx*.003;pitch=Math.max(-1.3,Math.min(1.3,pitch-dy*.003));F.camera.rotation.set(pitch,yaw,0);}});c.addEventListener('pointerup',e=>{drag=false;if(Math.hypot(e.clientX-down.x,e.clientY-down.y)<5&&state.mode==='after'){const rect=c.getBoundingClientRect(),ray=new F.T.Raycaster();ray.setFromCamera({x:(e.clientX-rect.left)/rect.width*2-1,y:-(e.clientY-rect.top)/rect.height*2+1},F.camera);let hits=ray.intersectObjects(F.upgrade.root.children,true);for(let h of hits){let o=h.object;while(o&&o!==F.scene){if(/^Z0[1-8]$/.test(o.name)){chooseZone(o.name);return}o=o.parent;}}}});c.addEventListener('wheel',e=>{e.preventDefault();if(state.view==='bird'){orbit.r=Math.max(30,Math.min(100,orbit.r+e.deltaY*.025));updateOrbit();}else F.camera.fov=Math.max(40,Math.min(100,F.camera.fov+e.deltaY*.025));F.camera.updateProjectionMatrix();},{passive:false});new ResizeObserver(()=>{let r=$('viewport').getBoundingClientRect();if(r.width&&r.height){F.renderer.setSize(r.width,r.height);F.camera.aspect=r.width/r.height;F.camera.updateProjectionMatrix()}}).observe($('viewport'));view('interior');let prev=performance.now();function frame(t){let dt=Math.min((t-prev)/1000,.05);prev=t;if(state.walk&&!$('modal').open){let speed=(keys.ShiftLeft?5:2.5)*dt,fw=(keys.KeyW?1:0)-(keys.KeyS?1:0),side=(keys.KeyD?1:0)-(keys.KeyA?1:0);let len=Math.hypot(fw,side)||1;let dx=(-Math.sin(yaw)*fw+Math.cos(yaw)*side)*speed/len,dz=(-Math.cos(yaw)*fw-Math.sin(yaw)*side)*speed/len,p=F.camera.position;if(canMove(p.x+dx,p.z))p.x+=dx;if(canMove(p.x,p.z+dz))p.z+=dz;}if(state.view!=='plan')F.renderer.render(F.scene,F.camera);requestAnimationFrame(frame)}requestAnimationFrame(frame);}else{$('rendererNotice').hidden=false;['interior','bird','walk','roof'].forEach(id=>$(id).disabled=true);view('plan');}
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;keys[e.code]=true;if(state.walk&&['KeyW','KeyA','KeyS','KeyD','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&state.walk)view('interior')});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false;});
$('rendersBtn').onclick=()=>openModal('改造后的厂房 · 概念效果',`<p class="note">以下为与三维页面同源模型的离线渲染，非建成实景。教学优先布局保留柱网和屋架，划分八个实训功能区。</p><img src="assets/renovated-interior.jpg" alt="改造后室内概念效果" style="width:100%;border-radius:5px"><img src="assets/renovated-bird.jpg" alt="改造后去顶鸟瞰" style="width:100%;border-radius:5px;margin-top:18px"><p class="note">去顶鸟瞰为可视化表达，并非拆除屋顶的改造建议。</p>`);
$('tasksBtn').onclick=()=>{openModal('32 项实训任务库',`<div class="taskFilters"><input id="searchTasks" placeholder="搜索任务、交付物或专业"><select id="filterTasks"><option value="">全部分区</option>${D.zones.map(z=>`<option value="${z.id}">${z.id} ${z.short}</option>`).join('')}</select><button id="exportTasks">导出清单</button></div><p class="note">共 32 项、188 建议学时，供各专业按课程选用；不要求所有学生全修。综合项目可整合基础任务，不重复计学时。</p><div id="taskResults" class="taskGrid"></div>`);function filter(){let q=$('searchTasks').value.trim(),z=$('filterTasks').value;let ts=D.tasks.filter(t=>(!z||t.zone===z)&&(!q||JSON.stringify(t).includes(q)));$('taskResults').innerHTML=ts.length?ts.map(taskCard).join(''):'<p>没有匹配任务，请调整筛选条件。</p>';}filter();$('searchTasks').oninput=filter;$('filterTasks').onchange=filter;$('exportTasks').onclick=()=>{let rows=[['编号','分区','实训名称','主责专业','建议学时','输入','操作','交付物'],...D.tasks.map(t=>[t.id,t.zone,t.name,t.lead,t.hours,t.input,t.action,t.output])];let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='昆冶实训任务清单.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}};
$('projectsBtn').onclick=()=>openModal('跨专业综合项目',D.projects.map(p=>`<article class="projectCard"><span class="zoneId">${p.id} / 建议 ${p.hours} 学时</span><h3>${p.name}</h3><p>${p.scope}</p><p><b>分工</b>　${p.roles}</p><p><b>共同交付</b>　${p.outputs}</p></article>`).join(''));
$('referenceBtn').onclick=()=>openModal('原始厂房资料',`<p class="note">以下为提供的原始照片与视频。模型依据可见结构推估；被遮挡部位、尺寸及设备权属尚未核实。</p><div class="refGrid">${[1,2,3].map(i=>`<a href="assets/reference-${i}.jpg" target="_blank"><img src="assets/reference-${i}.jpg" alt="原始厂房照片 ${i}"></a>`).join('')}</div><video src="assets/reference.mp4" controls preload="metadata"></video>`);
$('infoBtn').onclick=()=>openModal('方案说明与研究依据',`<h3>定位与实施边界</h3><p>围绕测绘工程技术专业群，形成“数据采集—资产生产—场景搭建—方案比选—监测运维—成果展示”的实训链。页面为可交互的概念布局，采用 Three.js 构建，尚未部署飞渡 DTS 平台或连接真实传感器。</p><p><b>建筑尺寸、承载、消防与现有设备迁移：</b>[!!! 事实断层：资料不足，无法确认]。照片推估尺寸仅用于可视化排布，须经现场测绘、设计及审查后实施。</p><h3>两种可切换布局</h3><p>A 教学优先：5 个协作组台、40 席；B 展示优先：保留3个组台、24席，新增2组景观展台与4块展示屏。以上为本模型家具配置，不代表现场额定容量。</p><h3>飞渡技术落点</h3><p>建议以 DTS Engine 承接多源成果转换与优化，Explorer 完成场景编排及空间分析、A/B联动视口，Cloud 支撑按需网络交付；物联数据经网关和数据服务标准化，再通过 API 关联孪生对象。航空摄影测量解算、物联协议适配和行业分析模型需单独核实配置。</p><h3>公开研究依据</h3>${D.sources.map(s=>`<a class="sourceLink" href="${s.url}" target="_blank" rel="noopener">[${s.id}] ${s.title}</a>`).join('')}<p class="note">检索核验日期：2026-11-11。专业群组合沿用用户给定范围，正式立项以学校确认文件为准。</p>`);
let values=Array.from({length:40},()=>24),tick=0;function sensorUpdate(){tick++;let val=state.sensor==='alarm'?35.5+Math.sin(tick)*.2:24+Math.sin(tick*.4)*.4;values.push(state.sensor==='offline'?values.at(-1):val);values.shift();$('temperature').textContent=state.sensor==='offline'?'—':val.toFixed(1);$('sensorStatus').textContent=state.sensor==='alarm'?'超限 · 模拟阈值 30°C / 待处理':state.sensor==='offline'?'离线 · 已停止演示数据更新':'正常 · 演示采样中';$('sensorStatus').style.color=state.sensor==='normal'?'#638475':'#b16454';$('spark').querySelector('polyline').setAttribute('points',values.map((v,i)=>`${i*260/39},${45-(v-22)*2.8}`).join(' '));if(F)F.upgrade.sensors[5].material.color.set(state.sensor==='normal'?'#72a386':state.sensor==='alarm'?'#dc6a52':'#777777');}
$('alarm').onclick=()=>{state.sensor='alarm';sensorUpdate()};$('offline').onclick=()=>{state.sensor='offline';sensorUpdate()};$('resetSensor').onclick=()=>{state.sensor='normal';sensorUpdate()};setInterval(sensorUpdate,1500);renderZones();updateMode();sensorUpdate();window.TrainingBaseApp={state,chooseZone,view,canMove,updateMode};
})();
